35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    public String getCustomerCode() {
61	        return this.customerCode;
62	    }
63	
64	    public void setCustomerCode(String customerCode) {
65	        this.customerCode = customerCode;
66	    }
67	
68	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
69	    private Set<Pet> pets;
70	
71	    public LocalDate getRegistrationDate() {
72	        return this.registrationDate;
73	    }
74	
75	    public void setRegistrationDate(LocalDate registrationDate) {
76	        this.registrationDate = registrationDate;
77	    }
78	
79	    @PrePersist
80	    void defaultRegistrationDate() {
81	        if (this.registrationDate == null) {
82	            this.registrationDate = LocalDate.now();
83	        }
84	    }
85	
86	    public String getEmail() {
87	        return this.email;
88	    }
89	
90	    public void setEmail(String email) {
91	        this.email = email;
92	    }
93	
94	    public String getAddress() {
95	        return this.address;
96	    }
97	
98	    public void setAddress(String address) {
99	        this.address = address;
100	    }
101	
102	    public String getCity() {
103	        return this.city;
104	    }
105	
106	    public void setCity(String city) {
107	        this.city = city;
108	    }
109	
110	    public String getTelephone() {
111	        return this.telephone;
112	    }
113	
114	    public void setTelephone(String telephone) {
115	        this.telephone = telephone;
116	    }
117	
118	    protected Set<Pet> getPetsInternal() {
119	        if (this.pets == null) {
120	            this.pets = new HashSet<>();
121	        }
122	        return this.pets;
123	    }
124	
125	    protected void setPetsInternal(Set<Pet> pets) {
126	        this.pets = pets;
127	    }
128	
129	    public List<Pet> getPets() {
130	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
131	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
132	        return Collections.unmodifiableList(sortedPets);
133	    }
134	
135	    public void setPets(List<Pet> pets) {
136	        this.pets = new HashSet<>(pets);
137	    }
138	
139	    public void addPet(Pet pet) {
140	        getPetsInternal().add(pet);
141	        pet.setOwner(this);
142	    }
143	
144	    /**
145	     * Return the Pet with the given name, or null if none found for this Owner.
146	     *
147	     * @param name to test
148	     * @return true if pet name is already in use
149	     */
150	    public Pet getPet(String name) {
151	        return getPet(name, false);
152	    }
153	
154	    /**
155	     * Return the Pet with the given name, or null if none found for this Owner.
156	     *
157	     * @param name to test
158	     * @return true if pet name is already in use
159	     */
160	    public Pet getPet(String name, boolean ignoreNew) {
161	        name = name.toLowerCase();
162	        for (Pet pet : getPetsInternal()) {
163	            if (!ignoreNew || !pet.isNew()) {
164	                String compName = pet.getName();
165	                compName = compName.toLowerCase();
166	                if (compName.equals(name)) {
167	                    return pet;
168	                }
169	            }
170	        }
171	        return null;
172	    }
173	
174	    public Pet getPet(Integer petId) {
175	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
176	    }
177	
178	    @Override
179	    public String toString() {
180	        return new ToStringCreator(this)
181	
182	            .append("id", this.getId())
183	            .append("new", this.isNew())
184	            .append("lastName", this.getLastName())
185	            .append("firstName", this.getFirstName())
186	            .append("address", this.address)
187	            .append("city", this.city)
188	            .append("telephone", this.telephone)
189	            .toString();
190	    }
191	}
