7	/**
8	 * Detects owners that share a household, i.e. have the same last name and address
9	 * (compared case-insensitively with collapsed whitespace).
10	 */
11	final class HouseholdDuplicates {
12	
13	    private HouseholdDuplicates() {
14	    }
15	
16	    /**
17	     * Returns {@code true} when an existing owner shares {@code candidate}'s household and the
18	     * request did not opt in via {@code sharesHousehold}.
19	     */
20	    static boolean isRejectedDuplicate(Owner candidate, Collection<Owner> existing, Boolean sharesHousehold) {
21	        if (Boolean.TRUE.equals(sharesHousehold)) {
22	            return false;
23	        }
24	        String key = key(candidate);
25	        return existing.stream().anyMatch(other -> key(other).equals(key));
26	    }
27	
28	    private static String key(Owner owner) {
29	        return norm(owner.getLastName()) + "\n" + norm(owner.getAddress());
30	    }
31	
32	    private static String norm(String value) {
33	        return value == null ? "" : value.replaceAll("\\s+", " ").trim().toLowerCase();
34	    }
35	}
